async function fetchRevenue() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json()
  return data.revenue as { month: string; amount: number }[]
}

export async function RevenueChart() {
  const revenue = await fetchRevenue()

  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

async function fetchLatestInvoices() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json()
  return data.invoices as { id: string; name: string; amount: number }[]
}

export async function LatestInvoices() {
  const invoices = await fetchLatestInvoices()

  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

async function fetchCardData() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json()
  return {
    totalRevenue: data.totalRevenue as number,
    totalInvoices: data.totalInvoices as number,
  }
}

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await fetchCardData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

